extends Interactable
class_name WaterVendor

@export var price := 2.0

func _ready() -> void:
    add_to_group("interactable")
    prompt_ar = "اشري ماء معدني"

func can_interact(_actor: Node) -> bool:
    return enabled and not GameState.water_shortage and GameState.money >= price

func interact(actor: Node) -> void:
    if not can_interact(actor):
        return
    GameState.add_money(-price)
    GameState.set_stat("water", 100.0)
    if GameState.missions.get("find_water") == "active":
        get_tree().call_group("mission_manager", "complete", "find_water")
    interacted.emit(actor)

extends Node
class_name JobSystem

signal offer_selected(job_id: String, label_ar: String)
signal job_completed(job_id: String, pay: float)
signal job_rejected(job_id: String, reason: String)

const OFFERS_PATH := "res://data/jobs/job_offers.json"

var clock: WorldClock
var economy: EconomyManager
var offers: Dictionary = {}
var selected_job_id := ""

func _ready() -> void:
    _load_offers()

func configure(c: WorldClock, e: EconomyManager) -> void:
    clock = c
    economy = e

func available_offers(district: String) -> Array[Dictionary]:
    var result: Array[Dictionary] = []
    if clock == null:
        return result
    var hour := clock.current_hour()
    for id in offers.keys():
        var offer: Dictionary = offers[id]
        if str(offer.get("district","")) != district:
            continue
        var availability: Dictionary = offer.get("availability", {})
        var start_hour := int(availability.get("start_hour", 0))
        var end_hour := int(availability.get("end_hour", 24))
        if hour >= start_hour and hour < end_hour:
            result.append(offer)
    return result

func select_offer(job_id: String) -> bool:
    if not offers.has(job_id):
        job_rejected.emit(job_id, "unknown_job")
        return false
    var offer: Dictionary = offers[job_id]
    var current := available_offers(str(offer.get("district","")))
    var found := false
    for item in current:
        if str(item.get("id","")) == job_id:
            found = true
            break
    if not found:
        job_rejected.emit(job_id, "outside_work_hours")
        return false
    selected_job_id = job_id
    offer_selected.emit(job_id, str(offer.get("label_ar", job_id)))
    return true

func complete_selected_job() -> bool:
    if selected_job_id.is_empty():
        job_rejected.emit("", "no_selected_job")
        return false
    if economy == null:
        job_rejected.emit(selected_job_id, "economy_unavailable")
        return false
    var id := selected_job_id
    var ok := economy.complete_job(id)
    if ok:
        var offer: Dictionary = offers.get(id,{})
        job_completed.emit(id, float(offer.get("pay", 0.0)))
        selected_job_id = ""
    else:
        job_rejected.emit(id, "economy_rejected")
    return ok

func serialize() -> Dictionary:
    return {"selected_job_id": selected_job_id}

func restore(data: Dictionary) -> void:
    var restored_id := str(data.get("selected_job_id", ""))
    # Content updates may remove/rename offers. Never restore a dangling active job.
    selected_job_id = restored_id if restored_id.is_empty() or offers.has(restored_id) else ""

func _load_offers() -> void:
    if not FileAccess.file_exists(OFFERS_PATH):
        return
    var f := FileAccess.open(OFFERS_PATH, FileAccess.READ)
    if f == null:
        return
    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) != TYPE_DICTIONARY:
        return
    for entry in parsed.get("offers", []):
        if typeof(entry) == TYPE_DICTIONARY:
            offers[str(entry.get("id",""))] = entry

extends Node
class_name DynamicObjectiveManager

signal dynamic_objective_changed(text: String)

var world_events: WorldEventScheduler
var job_system: JobSystem
var current_text := ""

func configure(events: WorldEventScheduler, jobs: JobSystem) -> void:
    world_events = events
    job_system = jobs
    if world_events:
        world_events.event_started.connect(_on_event_started)
        world_events.event_ended.connect(_on_event_ended)
    if job_system:
        job_system.offer_selected.connect(_on_offer_selected)
        job_system.job_completed.connect(_on_job_completed)

func _on_event_started(id: String, label_ar: String) -> void:
    match id:
        "fuel_shortage":
            _set_text("الإيصنص ناقص — دبّر تنقلك قبل ما يوفى")
        "water_shortage":
            _set_text("الماء المعدني مقطوع — لوج على حانوت آخر")
        "blackout":
            _set_text("الضو قصّ — استنى رجوع الكهرباء")
        _:
            _set_text(label_ar)

func _on_event_ended(id: String) -> void:
    if id in ["fuel_shortage","water_shortage","blackout"]:
        _set_text("الوضع رجع عادي")

func _on_offer_selected(_job_id: String, label_ar: String) -> void:
    _set_text("الخدمة: " + label_ar + " — ارجع لنفس النقطة لإكمال الشيفت")

func _on_job_completed(_job_id: String, pay: float) -> void:
    _set_text("كملت الخدمة وربحت %.1f د.ت" % pay)

func _set_text(value: String) -> void:
    current_text = value
    dynamic_objective_changed.emit(value)


func bind_rest_system(system) -> void:
    if system != null:
        system.rested.connect(_on_rested)
        system.rest_rejected.connect(_on_rest_rejected)

func _on_rested(kind: String, energy_gain: float) -> void:
    var label := "استراحة" if kind == "bench_rest" else "رقاد"
    _set_text("%s — رجعتلك %.0f طاقة" % [label, energy_gain])

func _on_rest_rejected(_kind: String, reason: String) -> void:
    if reason == "not_enough_water":
        _set_text("ما تنجمش ترتاح: الماء ناقص")

extends Node
class_name AdaptiveQualityManager

signal tier_changed(tier_name: String)

const PROFILE_PATH := "res://data/performance/mobile_budget.json"

var profile: Dictionary = {}
var tier_order := ["LOW", "MEDIUM", "HIGH"]
var tier_index := 1
var sample_time := 0.0
var fps_sum := 0.0
var fps_samples := 0
var low_windows := 0
var high_windows := 0
var last_average_fps := 0.0
var manual_tier := ""

func _ready() -> void:
    _load_profile()
    SettingsService.quality_mode_changed.connect(set_quality_mode)
    set_quality_mode(SettingsService.quality_mode())

func _process(delta: float) -> void:
    if not manual_tier.is_empty():
        return
    if delta <= 0.0:
        return
    sample_time += delta
    fps_sum += 1.0 / delta
    fps_samples += 1

    var window := float(profile.get("sample_window_seconds", 6.0))
    if sample_time < window:
        return

    last_average_fps = fps_sum / maxf(1.0, float(fps_samples))
    sample_time = 0.0
    fps_sum = 0.0
    fps_samples = 0
    _evaluate(last_average_fps)

func _evaluate(avg_fps: float) -> void:
    var target := float(profile.get("target_fps", 60))
    var hard_floor := float(profile.get("hard_floor_fps", 30))
    var degrade_after := int(profile.get("degrade_after_windows", 2))
    var upgrade_after := int(profile.get("upgrade_after_windows", 4))

    if avg_fps < hard_floor:
        low_windows += 2
        high_windows = 0
    elif avg_fps < target * 0.82:
        low_windows += 1
        high_windows = 0
    elif avg_fps > target * 0.96:
        high_windows += 1
        low_windows = 0
    else:
        low_windows = 0
        high_windows = 0

    if low_windows >= degrade_after and tier_index > 0:
        tier_index -= 1
        low_windows = 0
        apply_tier(tier_order[tier_index])
    elif high_windows >= upgrade_after and tier_index < tier_order.size() - 1:
        tier_index += 1
        high_windows = 0
        apply_tier(tier_order[tier_index])

func set_quality_mode(mode: String) -> void:
    var clean := mode.to_upper()
    if clean == "AUTO":
        manual_tier = ""
        low_windows = 0
        high_windows = 0
        if tier_index < 0 or tier_index >= tier_order.size():
            tier_index = 1
        apply_tier(tier_order[tier_index])
        return
    if clean not in tier_order:
        clean = "MEDIUM"
    manual_tier = clean
    low_windows = 0
    high_windows = 0
    apply_tier(clean)

func quality_mode() -> String:
    return "AUTO" if manual_tier.is_empty() else manual_tier

func apply_tier(tier_name: String) -> void:
    var tiers = profile.get("tiers", {})
    if typeof(tiers) != TYPE_DICTIONARY:
        return
    var cfg = tiers.get(tier_name, {})
    if typeof(cfg) != TYPE_DICTIONARY:
        return

    var idx := tier_order.find(tier_name)
    if idx >= 0:
        tier_index = idx

    get_viewport().scaling_3d_scale = float(cfg.get("render_scale", 0.86))
    get_tree().call_group(
        "population_spawner",
        "apply_population_budget",
        int(cfg.get("pedestrians", 18)),
        int(cfg.get("traffic", 7))
    )
    get_tree().call_group(
        "osm_world",
        "apply_visibility_budget",
        float(cfg.get("osm_visibility_m", 95.0))
    )
    get_tree().call_group(
        "quality_visual_detail",
        "apply_visual_budget",
        int(cfg.get("street_detail_level", 1))
    )
    tier_changed.emit(tier_name)

func current_tier() -> String:
    return tier_order[tier_index]

func _load_profile() -> void:
    if not FileAccess.file_exists(PROFILE_PATH):
        profile = {}
        return
    var f := FileAccess.open(PROFILE_PATH, FileAccess.READ)
    if f == null:
        profile = {}
        return
    var parsed = JSON.parse_string(f.get_as_text())
    profile = parsed if typeof(parsed) == TYPE_DICTIONARY else {}
